import functools
import time

def retry(times: int, delay: float = 0):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last: Exception | None = None
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except Exception as e:
                    last = e
                    if attempt < times:
                        time.sleep(delay)
            raise last
        return wrapper
    return deco

calls = {"n": 0}

@retry(times=3)
def flaky() -> str:
    calls["n"] += 1
    if calls["n"] < 3:
        raise ValueError("boom")
    return "ok"

print(flaky(), "after", calls["n"], "attempts")

